To ensure that the easing works for both positive and negative offset distances, you need to adjust the easing logic to handle negative values correctly. This can be done by using the `Math.sign` function to preserve the sign of the offset while reducing its magnitude.

Here's the updated code:

```javascript
p.setup = function () {
  img.resize(600, 0);
  p.createCanvas(img.width, img.height);
};

p.draw = function () {
  if (needsRedraw) {
    console.log(xOffsets, yOffsets);
    const processedImg = shiftImage(img, xOffsets, yOffsets);
    console.log("redrew!");
    p.image(processedImg, 0, 0);
    needsRedraw = false;
  }

  if (!dragging && (!isEasingDone(xOffsets) || !isEasingDone(yOffsets))) {
    // Ease back to 0
    console.log('easing!')
    for (let i = 0; i < 3; i++) {
      xOffsets[i] -= Math.sign(xOffsets[i]) * easing * Math.abs(xOffsets[i]);
      yOffsets[i] -= Math.sign(yOffsets[i]) * easing * Math.abs(yOffsets[i]);
    }
    needsRedraw = true;
  }
};

p.mousePressed = function () {
  dragStart = new p5.Vector(p.mouseX, p.mouseY);
};

p.mouseDragged = function () {
  dragging = true;
  let dx = p.mouseX - dragStart.x;
  let dy = p.mouseY - dragStart.y;
  xOffsets = [dx * 0.8, dx * 1.2, dx * 1.8];
  yOffsets = [dy * 0.8, dy * 1.2, dy * 1.8];
  needsRedraw = true;
};
```

This modification ensures that the offsets are reduced towards zero regardless of whether they are positive or negative.
